const assert = require('assert');
const leftPad = require('./index.js');

const cases = [
  [['foo', 5], '  foo'],
  [['foo', 5, '-'], '--foo'],
  [['foo', 2], 'foo'],
  [['foo', 3], 'foo'],
  [[42, 5, '0'], '00042'],
  [['', 3, '*'], '***'],
  [['hello', 0], 'hello'],
  [['hello', -1], 'hello'],
  [['abc', 6, 'ab'], 'abaabc'],
  [[null, 4, '.'], '..nu'],
  [[undefined, 4, '.'], '....'],
  [[{toString(){return 'x'}}, 3, '-'], '--x'],
];

for (const [[args, expected], i] of cases.map((c,i)=>[c,i])) {
  const got = leftPad(...args);
  assert.strictEqual(got, expected, 'case ' + i + ' args=' + JSON.stringify(args));
  console.log('ok  ' + JSON.stringify(args) + ' -> ' + JSON.stringify(got));
}

// default ch is a single space
assert.strictEqual(leftPad('a', 4), '   a');
// non-integer len
assert.strictEqual(leftPad('a', 4.7), '   a');
// ch = '' must not loop forever
assert.strictEqual(leftPad('a', 5, ''), 'a');
// module shapes
assert.strictEqual(require('./index.js').leftPad('q', 3, 'z'), 'zzq');
assert.strictEqual(require('./index.js').default('q', 3, 'z'), 'zzq');
console.log('all index.js assertions passed');
""}

